UPDATE albums SET name=CASE WHEN (SELECT COUNT(*) FROM snapshot s JOIN song_masters sm ON sm.id=s.master_id JOIN song_instances si ON si.id=s.instance_id AND si.master_id=sm.id JOIN storage_objects so ON so.id=si.storage_object_id JOIN storage_entries se ON se.id=s.entry_id AND se.instance_id=si.id AND se.object_id=so.id WHERE sm.album_id='al-chromatic-wav-20260926' AND sm.title=s.title AND sm.duration=s.duration AND sm.track=s.new_track AND sm.disc=s.new_disc AND si.suffix=s.suffix AND si.size=s.size AND so.physical_key=s.physical_key AND se.parent_id=s.parent_id AND se.path=s.path)=24 AND (SELECT COUNT(*) FROM album_display_group_members WHERE group_id='ag-chromatic-audio-versions-20260926')=2 AND song_count=(SELECT COUNT(*) FROM song_masters WHERE album_id='al-chromatic-wav-20260926') AND duration=(SELECT COALESCE(SUM(duration),0) FROM song_masters WHERE album_id='al-chromatic-wav-20260926') AND size=(SELECT COALESCE(SUM(si.size),0) FROM song_instances si JOIN song_masters sm ON sm.id=si.master_id WHERE sm.album_id='al-chromatic-wav-20260926') THEN name ELSE NULL END,updated_at=unixepoch() WHERE id='al-chromatic-wav-20260926';
